"""Self-contained dashboard: works offline and on GitHub Pages without a server."""
from __future__ import annotations
import json
from datetime import datetime, timezone


def demo_report() -> dict:
    fake = [
        ('example-labs/agent-studio', 2468, 'TypeScript', 'AI & Agents', 'Build small autonomous workflows with a visual editor.'),
        ('example-labs/fast-infer', 1987, 'Rust', 'AI & Agents', 'A lightweight inference engine for local experimentation.'),
        ('example-labs/terminal-x', 1650, 'Go', 'Developer Tools', 'A modern terminal workflow toolkit.'),
        ('example-labs/linux-probe', 1320, 'C', 'Embedded & Systems', 'Explore Linux internals with practical tracing tools.'),
        ('example-labs/cloudcraft', 1198, 'Go', 'Cloud & DevOps', 'A declarative deployment orchestrator.'),
        ('example-labs/pixel-ui', 985, 'TypeScript', 'Web & UI', 'Accessible components for fast web applications.'),
        ('example-labs/db-fusion', 872, 'Rust', 'Data & Database', 'Experimental real-time analytics engine.'),
        ('example-labs/agent-eval', 744, 'Python', 'AI & Agents', 'Benchmark and compare agentic workflows.'),
        ('example-labs/netstack', 635, 'C++', 'Embedded & Systems', 'A minimal packet-processing lab.'),
        ('example-labs/safe-scan', 509, 'Python', 'Security', 'Open-source scanner for secure development.'),
    ]
    repos = []
    for i, (name, stars, language, category, description) in enumerate(fake, 1):
        repos.append({'rank': i, 'name': name, 'weekly_stars': stars,
                      'total_stars': stars * 3, 'language': language, 'category': category,
                      'description': description, 'url': 'https://github.com/', 'topics': [],
                      'candidate_sources': ['synthetic-demo']})
    return {'schema_version': 1, 'week_id': '2026-10-04', 'window': 'DEMO – simulated week',
            'basis': 'synthetic-demo', 'collected_at': datetime.now(timezone.utc).isoformat(),
            'candidate_count': 85, 'ranked_candidate_count': 85,
            'history_api_success_count': 85, 'methodology': 'DEMO ONLY: fictional repositories and star counts.',
            'repos': repos}


def render_dashboard(reports: list[dict]) -> str:
    # Avoid HTML parser ending <script> if any GitHub description contains markup.
    payload = json.dumps(reports, ensure_ascii=False, separators=(',', ':')).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    # Self-contained: no HTTP request needed, opens directly in Safari/Chrome.
    page = r'''<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"/>
<meta name="color-scheme" content="dark"/>
<title>GitHub Trend Radar · Weekly star-growth leaderboard</title>
<style>
:root{--bg:#080d17;--surface:#101a2b;--surface2:#142136;--stroke:#243650;--text:#f5f8ff;--muted:#96a7bf;--accent:#86f3cc;--blue:#75aef7;--gold:#ffd47d;--shadow:0 28px 90px rgba(0,0,0,.2)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse 1200px 550px at 85% -8%,#163c46 0%,transparent 65%),linear-gradient(180deg,#0b1423,#080d17 40%);color:var(--text);font:15px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Arial,sans-serif;min-height:100vh}
a{color:inherit;text-decoration:none}button,select,input{font:inherit}.shell{max-width:1240px;margin:auto;padding:32px 26px 92px}.topnav{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:66px}.brand{display:flex;align-items:center;gap:13px;font-size:16px;font-weight:850;letter-spacing:.3px}.brandmark{display:grid;place-items:center;width:40px;height:40px;border-radius:13px;background:linear-gradient(130deg,#63bba6,#81e9cb);color:#06211d;font-size:22px}.navtag{border:1px solid #31514e;color:#acf4df;background:#132a2d;border-radius:999px;padding:7px 12px;font-size:12px;font-weight:700;letter-spacing:.08em}.headline{max-width:900px}.eyebrow{color:var(--accent);font-weight:800;text-transform:uppercase;letter-spacing:.2em;font-size:11px;margin-bottom:16px}.hero-title{font-size:clamp(40px,6vw,74px);font-weight:850;letter-spacing:-.065em;line-height:1.03;margin:0 0 20px}.hero-title span{background:linear-gradient(100deg,#fff,#8aefd1);color:transparent;background-clip:text}.subtitle{font-size:17px;color:#afc0d5;max-width:700px;margin:0}.intro{display:flex;gap:30px;align-items:flex-end;justify-content:space-between;margin-bottom:46px}.windowline{display:flex;align-items:center;gap:9px;color:var(--muted);font-size:13px;margin-top:20px}.pulse{display:inline-block;width:7px;height:7px;border-radius:50%;background:#83eecd;box-shadow:0 0 0 5px #83eecd22}
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin:35px 0 30px}.stat{background:#101b2bba;border:1px solid #263b4c;border-radius:17px;padding:21px 22px;min-height:108px}.stat small{font-size:12px;color:var(--muted);display:block;font-weight:650}.stat b{font-size:30px;letter-spacing:-.04em;display:block;margin-top:4px}.stat .aside{font-size:13px;color:var(--accent)}
.main-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:25px;align-items:start}.panel{background:#0f192a;border:1px solid #22344a;border-radius:20px;box-shadow:var(--shadow)}.leaderboard{padding:25px}.sectionline{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:19px}.sectionline h2,.insights h2{margin:0;font-size:19px;letter-spacing:-.025em}.section-sub{color:var(--muted);font-size:12px}.filters{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:21px}.control{border:1px solid #2b4058;background:#142136;color:var(--text);padding:10px 12px;border-radius:10px;min-width:0;outline:none}.control:focus{border-color:var(--accent)}#search{flex:1;min-width:180px}select{max-width:180px}.repo{padding:18px 0 19px;border-top:1px solid #243249}.repohead{display:grid;grid-template-columns:36px minmax(0,1fr) auto;gap:12px;align-items:start}.rank{color:#8298b4;font-size:16px;font-weight:800;padding-top:2px}.rank.first{color:var(--gold)}.reponame{font-size:17px;letter-spacing:-.02em;font-weight:750;overflow-wrap:anywhere;line-height:1.35}.reponame:hover{color:var(--accent)}.desc{color:var(--muted);font-size:13px;margin:6px 0 11px;line-height:1.55;max-width:580px}.delta{font-size:23px;font-weight:850;letter-spacing:-.045em;color:var(--accent);text-align:right;line-height:1.1;white-space:nowrap}.delta small{display:block;font-size:10px;color:var(--muted);letter-spacing:0;font-weight:600;margin-top:5px}.tags{display:flex;gap:7px;flex-wrap:wrap;margin-top:6px}.tag{padding:4px 9px;border-radius:7px;background:#1b2b40;color:#b9cae0;font-size:11px;font-weight:650}.tag.category{background:#18342f;color:#9fe6d0}.meter{height:5px;border-radius:99px;background:#1e3042;overflow:hidden;margin-top:12px}.fill{background:linear-gradient(90deg,#427d90,#82e7be);height:100%;border-radius:99px}.insights{padding:24px;position:sticky;top:24px}.accent-line{height:3px;width:44px;background:var(--accent);margin:12px 0 20px;border-radius:9px}.micro{color:var(--muted);font-size:12px;line-height:1.65}.insight{margin:19px 0}.insighttop{display:flex;justify-content:space-between;align-items:center;font-size:12px;font-weight:650;margin-bottom:8px;gap:8px}.insightbar{background:#203149;height:7px;border-radius:99px;overflow:hidden}.insightfill{height:100%;background:#78b6f0;border-radius:99px}.footnote{margin-top:23px;border-top:1px solid #24384f;padding-top:17px;color:#9db2c9;font-size:12px}.notice{border:1px solid #4b4631;background:#292719;color:#fbe5ae;border-radius:10px;padding:12px 15px;font-size:13px;margin-bottom:18px}.download{display:flex;gap:10px;flex-wrap:wrap;margin-top:17px}.pill{border:1px solid #3d4d60;padding:8px 12px;font-size:12px;border-radius:9px;color:#c6d6ea}.pill:hover{border-color:var(--accent)}.empty{color:var(--muted);padding:20px 0}.footer{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;color:#6f86a4;font-size:12px;margin-top:30px;border-top:1px solid #1c293c;padding-top:25px}
@media(max-width:960px){.main-layout{grid-template-columns:1fr}.insights{position:static}.stats{grid-template-columns:repeat(2,1fr)}.topnav{margin-bottom:42px}}
@media(max-width:560px){.shell{padding:22px 15px 56px}.topnav{margin-bottom:44px}.hero-title{font-size:43px}.subtitle{font-size:14px}.stats{gap:9px}.stat{padding:14px 14px;min-height:88px}.stat b{font-size:24px}.leaderboard,.insights{padding:16px}.repohead{grid-template-columns:23px minmax(0,1fr) auto;gap:7px}.rank{font-size:14px}.reponame{font-size:14px}.desc{font-size:12px}.delta{font-size:19px}.delta small{font-size:9px}.filters{flex-wrap:wrap}#search{flex-basis:100%}select{flex:1;max-width:unset}.sectionline h2{font-size:17px}.navtag{font-size:10px}}
</style></head><body>
<main class="shell">
<header class="topnav"><div class="brand"><span class="brandmark">✳</span> GitHub Trend Radar</div><span class="navtag">WEEKLY TECH INTELLIGENCE</span></header>
<section class="intro"><div class="headline"><div class="eyebrow">Open-source · Signal tracker</div><h1 class="hero-title">Catch what’s <span>rising.</span></h1><p class="subtitle">See which GitHub projects are gaining attention fastest, discover new tools, and spot emerging technology trends before they become mainstream.</p><div class="windowline"><span class="pulse"></span><span id="window-label">Loading report...</span></div></div></section>
<section class="stats" aria-label="Summary"><div class="stat"><small>Tracked repositories</small><b id="s-candidates">–</b></div><div class="stat"><small>Stars gained · Top 10</small><b id="s-stars">–</b></div><div class="stat"><small>Most active category</small><b id="s-category" style="font-size:19px;margin-top:11px">–</b></div><div class="stat"><small>Languages in Top 10</small><b id="s-languages">–</b></div></section>
<div id="warning" class="notice" hidden></div>
<div class="main-layout"><section class="panel leaderboard"><div class="sectionline"><div><h2>Trending repositories</h2><div class="section-sub">Ranked by newly added stars · not lifetime total</div></div><select id="week" class="control" aria-label="Select week"></select></div><div class="filters"><input id="search" class="control" type="search" placeholder="Search repos, tools, topics…" aria-label="Search repositories"/><select id="lang" class="control" aria-label="Language"><option value="">All languages</option></select><select id="category" class="control" aria-label="Category"><option value="">All categories</option></select></div><div id="repos"></div></section>
<aside class="panel insights"><h2>Trend signals</h2><div class="accent-line"></div><div class="micro">Technology themes among this week's Top 10. These are lightweight keyword labels, not expert assessments.</div><div id="categories"></div><div class="footnote"><strong>Reading this chart</strong><p>Growth measures interest. Check a project's README, contributors, releases, and security practices before adopting it.</p><p id="method"></p></div><div class="download"><a class="pill" href="../reports/latest.md" id="report-link">Read latest report ↗</a><button class="pill" id="jsonbtn" type="button" style="cursor:pointer;background:transparent">Export selected week JSON ↓</button></div></aside></div>
<footer class="footer"><span>GitHub Trend Radar · Open source, zero backend</span><span>Collection via GitHub Trending + GitHub REST API</span></footer>
</main><script id="embedded-data" type="application/json">__DATA__</script><script>
(() => {
const reports = JSON.parse(document.getElementById('embedded-data').textContent || '[]');
const $=id=>document.getElementById(id);
const format=n=>Number(n||0).toLocaleString('en-US');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const select=(id,values)=>{const el=$(id),keep=el.value;el.innerHTML='<option value="">All '+(id==='lang'?'languages':'categories')+'</option>'+[...new Set(values)].filter(Boolean).sort().map(v=>`<option value="${escape(v)}">${escape(v)}</option>`).join('');if([...el.options].some(o=>o.value===keep))el.value=keep;};
if(!reports.length){$('repos').innerHTML='<div class="empty">No report yet. Run the GitHub Actions workflow manually to generate the first live report.</div>';$('window-label').textContent='Awaiting the first live report';$('report-link').hidden=true;return;}
reports.forEach((r,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=r.window || r.week_id;$('week').appendChild(o)});
const current=()=>reports[Number($('week').value||0)];
const themes=rows=>{let counts={};rows.forEach(r=>counts[r.category||'Other']=(counts[r.category||'Other']||0)+1);return Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));};
function draw(){const r=current();if(!r)return;const rows=r.repos||[],cats=themes(rows),max=Math.max(1,...rows.map(x=>x.weekly_stars||0));$('window-label').textContent=r.window+'  ·  Updated '+new Date(r.collected_at).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'});$('s-candidates').textContent=format(r.candidate_count);$('s-stars').textContent='+'+format(rows.reduce((s,x)=>s+(x.weekly_stars||0),0));$('s-category').textContent=cats[0]?.[0]||'–';$('s-languages').textContent=new Set(rows.map(x=>x.language).filter(Boolean)).size;select('lang',rows.map(x=>x.language||'Unknown'));select('category',rows.map(x=>x.category||'Other'));
const isDemo=r.basis==='synthetic-demo',isRolling=r.basis==='github-trending-rolling-week';$('warning').hidden=!(isDemo||isRolling);$('warning').textContent=isDemo?'DEMO MODE — All names and star counts in this preview are fictional. Run the workflow to load real GitHub data.':isRolling?'Fallback mode: star counts come from GitHub Trending’s rolling-week window, not the last completed calendar week.':'';
$('method').textContent=(r.methodology||'')+' Metric: '+r.basis+'. Candidate pool: '+format(r.candidate_count)+'.';
$('categories').innerHTML=cats.map(([cat,n])=>`<div class="insight"><div class="insighttop"><span>${escape(cat)}</span><span>${n}/${rows.length}</span></div><div class="insightbar"><div class="insightfill" style="width:${100*n/Math.max(1,rows.length)}%"></div></div></div>`).join('');
renderRows();}
function renderRows(){const r=current(),rows=r.repos||[],max=Math.max(1,...rows.map(x=>x.weekly_stars||0)),q=$('search').value.trim().toLowerCase(),lang=$('lang').value,cat=$('category').value,filtered=rows.filter(x=>(!lang||x.language===lang)&&(!cat||x.category===cat)&&(!q||[x.name,x.description,x.category,x.language,...(x.topics||[])].join(' ').toLowerCase().includes(q)));$('repos').innerHTML=filtered.length?filtered.map(x=>`<article class="repo"><div class="repohead"><span class="rank ${x.rank===1?'first':''}">${String(x.rank).padStart(2,'0')}</span><div><a class="reponame" href="${escape(x.url)}" target="_blank" rel="noopener noreferrer">${escape(x.name)} ↗</a><div class="desc">${escape(x.description||'No description provided.')}</div><div class="tags"><span class="tag">${escape(x.language||'Unknown')}</span><span class="tag category">${escape(x.category||'Other')}</span>${Number.isInteger(x.total_stars)?`<span class="tag">★ ${format(x.total_stars)} total</span>`:''}</div></div><div class="delta">+${format(x.weekly_stars)}<small>STARS / WEEK</small></div></div><div class="meter"><div class="fill" style="width:${Math.max(1,100*x.weekly_stars/max)}%"></div></div></article>`).join(''):'<div class="empty">No repositories match these filters.</div>'}
$('week').addEventListener('change',draw);$('search').addEventListener('input',renderRows);$('lang').addEventListener('change',renderRows);$('category').addEventListener('change',renderRows);
$('jsonbtn').addEventListener('click',()=>{const r=current(),blob=new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='github-trends-'+r.week_id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)});draw();
})();
</script></body></html>'''
    return page.replace('__DATA__', payload)
